/* eslint-disable @typescript-eslint/no-unused-vars -- port of the team's closure: dead locals and shapes stay as delivered */
// Literal port of the team's Casa3DSDK (module furniture/fixtures). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installFurnitureFixtures(K: Kernel, _shared: Shared): void {
  const seedKey = (id: any): any => K.seedKey(id);
  const { FURNITURE, MIRRORS, SEED, arcPoints, cursor, kit2, rngString, sh } = K;
  // shower: curved arm, round head, round valve (handle part), hidden water; stall with rounded corners and profiles
  FURNITURE.box = function (M, A) {
    const K = kit2(M, A, 0), w = M.w, d = M.d, cr = 0xc8ccd0, id = 'shower_' + (M.seed || ''), zw = -d / 2, X = w / 2 - 0.0;
    const R = Math.min(0.32, w * 0.34, d * 0.34), gh = 1.95, gt = 0.008;
    // tray: low slab, rounded edge and round drain
    K.b('plain', 0, 0, 0, w - 0.02, 0.05, d - 0.02, 0xe6e8e6); K.c('metal', 0, 0.05, 0, 0.045, 0.006, 0xb0b4b8); K.c('plain', 0, 0.05, 0, 0.032, 0.008, 0x40484c);
    // stall walls: back (-z) and side (-x). Glass: side (+x), 90 degree arc at the front corner and front panel with an access gap
    const px0 = w / 2 - 0.012, pzF = d / 2 - 0.012, gl = (x0, z0, x1, z1) => { const L = Math.hypot(x1 - x0, z1 - z0), a = Math.atan2(-(z1 - z0), x1 - x0); K.b('glass', (x0 + x1) / 2, 0.052, (z0 + z1) / 2, L + 0.004, gh - 0.052, gt, 0xffffff, a); };
    const tube = (p, q, r) => K.t('metal', p, q, r, cr);
    gl(px0, -d / 2 + 0.05, px0, pzF - R);                                                       // side
    const arc = arcPoints(px0 - R, pzF - R, R, 0, Math.PI / 2, 6);                                // curved corner (x,z)
    for (let i = 0; i < arc.length - 1; i++) gl(arc[i][0], arc[i][1], arc[i + 1][0], arc[i + 1][1]);
    const fx1 = Math.max(-w / 2 + 0.36, px0 - R - 0.5); gl(px0 - R, pzF, fx1, pzF);               // fixed front panel
    const rail = (y, r) => { tube([px0, y, -d / 2 + 0.05], [px0, y, pzF - R], r); for (let i = 0; i < arc.length - 1; i++) tube([arc[i][0], y, arc[i][1]], [arc[i + 1][0], y, arc[i + 1][1]], r); tube([px0 - R, y, pzF], [fx1, y, pzF], r); };
    rail(gh, 0.011); rail(0.055, 0.009);
    for (const [x, z] of [[px0, -d / 2 + 0.05], [fx1, pzF]]) tube([x, 0.05, z], [x, gh + 0.005, z], 0.011);
    for (const [x, y, z] of [[px0, gh, -d / 2 + 0.05], [fx1, gh, pzF], [px0 - R, gh, pzF]]) K.e('metal', x, y, z, 0.013, 0.026, cr);
    // swing door in the gap (up to the -x wall): glass with a round pull, hinged on the fixed panel
    const hx = fx1, dw = hx - (-w / 2 + 0.03);
    if (dw > 0.2) K.part('shower_door', hx, 0.06, pzF, () => { K.b('glass', hx - dw / 2, 0.06 + (gh - 0.12) / 2, pzF, dw, gh - 0.12, gt, 0xffffff); K.t('metal', [hx - dw * 0.8, 0.9, pzF + 0.02], [hx - dw * 0.8, 1.1, pzF + 0.02], 0.009, cr); K.e('metal', hx - dw * 0.8, 0.9, pzF + 0.02, 0.012, 0.02, cr); K.e('metal', hx - dw * 0.8, 1.1, pzF + 0.02, 0.012, 0.02, cr); },
      { id: id + '_door', opens: { type: 'swing', axis: [0, 1, 0], angle: -1.7 } });
    // curved arm and round head, at the centre of the back wall
    const ax = 0.1, ya = 2.08, z0 = zw + 0.012, Ra = 0.22, n = 6, pa = [];
    for (let i = 0; i <= n; i++) { const f = i / n * Math.PI / 2; pa.push([ax, ya - Ra * (1 - Math.cos(f)), z0 + Ra * Math.sin(f)]); }
    K.t('metal', [ax, ya, zw - 0.0], [ax, ya, z0 + 0.025], 0.03, cr);
    for (let i = 0; i < n; i++) K.t('metal', pa[i], pa[i + 1], 0.0125, cr);
    const ph = pa[n]; K.e('metal', ph[0], ph[1] - 0.005, ph[2], 0.026, 0.05, cr);
    const hy = ph[1] - 0.045; K.t('metal', [ph[0], ph[1] - 0.02, ph[2]], [ph[0], hy, ph[2]], 0.018, cr);
    K.c('metal', ph[0], hy - 0.012, ph[2], 0.115, 0.02, cr); K.c('plain', ph[0], hy - 0.0125, ph[2], 0.098, 0.006, 0xdadde0); K.c('metal', ph[0], hy - 0.022, ph[2], 0.0875, 0.01, 0xb8bcc0);
    // round valve: fixed base and rotating knob (handle part)
    const vx = ax, vy = 1.05; K.t('metal', [vx, vy, zw], [vx, vy, zw + 0.012], 0.052, cr);
    K.part('handle', vx, vy, zw + 0.012, () => { K.t('metal', [vx, vy, zw + 0.012], [vx, vy, zw + 0.04], 0.03, 0xb8bcc0); K.t('metal', [vx, vy, zw + 0.04], [vx, vy, zw + 0.052], 0.036, cr); K.b('metal', vx, vy + 0.03, zw + 0.046, 0.012, 0.032, 0.014, 0x8a8e92); },
      { id: id + '_m', target: id, room: M.room, opens: { type: 'swing', axis: [0, 0, 1], angle: 1.3 }, waterId: id + '_a' });
    // water (hidden): thin strands from the head to the floor
    K.part('water_shower', ph[0], hy - 0.03, ph[2], () => { for (let i = 0; i < 8; i++) { const a = i * Math.PI / 4, r1 = 0.07, r2 = 0.14; K.t('water', [ph[0] + Math.cos(a) * r1, hy - 0.03, ph[2] + Math.sin(a) * r1], [ph[0] + Math.cos(a) * r2, 0.06, ph[2] + Math.sin(a) * r2 + 0.05], 0.0045, 0xcfe8f4); } }, { id: id + '_a', target: id, hidden: true, fluid: 'water' });
  };
  // ---------- mirror with real reflection (45-espelho.js) ----------
  FURNITURE.mirror = function (M, A) {
    const w = M.w || 0.6, d = M.d || 0.03, h = M.h || 1.2, y = M.y || 0.9, K = kit2(M, A, 0), cm = M.color != null ? M.color : ((M.palette && M.palette.metal != null) ? M.palette.metal : 0x3a3a3c);
    K.b('plain', 0, y, 0, w, h, d, cm); // frame and back
    K.b('plain', 0, y + 0.012, d / 2 - 0.001, w - 0.045, h - 0.024, 0.004, 0x9aa4a8); // glass blanked until the reflection loads
    const [px, py, pz] = K.W(0, y + h / 2, d / 2 + 0.006);
    MIRRORS.push({ x: px, y: py, z: pz, ry: M.ry, w: w - 0.06, h: h - 0.06, room: M.room, floor: M.floor, parent: cursor.group });
  };
  // ---------- curtain: rod, rings and fabric pleats ('fabric' boxes, one list per side: 60-interacao.js cuts each side into a panel that opens and closes) ----------
  FURNITURE.curtain = function (M, A) {
    const w = M.w || 1.6, h = M.h || 2.3, y = M.y != null && M.y > 0 ? M.y : 0.1, K = kit2(M, A, 0), top = y + h;
    const rnd = rngString(SEED() + '|' + seedKey(M.seed) + '|cort'), color = M.color != null ? M.color : [0xd8cdb4, 0x9fb0be, 0xc5a88c, 0xe0dcd0][(rnd() * 4) | 0], gold = (M.palette && M.palette.metal != null) ? M.palette.metal : 0x5a5048;
    K.t('metal', [-w / 2 - 0.05, top + 0.02, 0], [w / 2 + 0.05, top + 0.02, 0], 0.012, gold); for (const s of [-1, 1]) K.e('metal', s * (w / 2 + 0.07), top + 0.02, 0, 0.022, 0.045, gold);
    const pw = w / 2 + 0.03, n = Math.max(8, Math.round(pw / 0.075));
    for (const s of [-1, 1]) for (let i = 0; i < n; i++) { const ux = s * (i + 0.5) * pw / n; K.b('fabric', ux, y, (i % 2 ? 0.03 : -0.012), pw / n * 1.12, h - 0.04, 0.018, i % 2 ? sh(color, 0.88) : color); }
    for (const s of [-1, 1]) for (let i = 0; i < n; i += 2) K.e('metal', s * (i + 0.5) * pw / n, top + 0.012, 0, 0.012, 0.024, gold);
  };
}
